#include <vector>

template <typename T>
int count_crossings(const std::vector<T>& xs, T level) {
    int n = 0;
    for (std::size_t i = 1; i < xs.size(); ++i) {
        if ((xs[i - 1] < level && level < xs[i]) || (level < xs[i - 1] && xs[i] < level)) ++n;
    }
    return n;
}

#include <vector>

template <typename T>
int count_crossings(const std::vector<T>& xs, T level) {
    int side = 0, n = 0;   // -1 below, +1 above, 0 not known yet
    for (const T& x : xs) {
        int s = level < x ? 1 : -1;
        if (s == 0) continue;
        if (side != 0 && s != side) ++n;
        side = s;
    }
    return n;
}
